using System;

namespace Nosum.Domain.World;

/// <summary>
/// One stack of items lying on the ground of a map instance (docs/adr/ADR-021 D5). Persisted so a crash does not lose a harvest;
/// picking it up deletes the row in the same transaction that adds the items to the inventory.
/// </summary>
public sealed class GroundItem
{
    /// <summary>Gets or sets the id, generated by the database and never reused.</summary>
    public long Id { get; set; }

    /// <summary>Gets or sets the map key.</summary>
    public string MapId { get; set; } = string.Empty;

    /// <summary>Gets or sets the owner of the instance; <see cref="Guid.Empty"/> for a shared map.</summary>
    public Guid OwnerId { get; set; }

    /// <summary>Gets or sets the item.</summary>
    public int ItemId { get; set; }

    /// <summary>Gets or sets how many lie there.</summary>
    public int Quantity { get; set; }

    /// <summary>Gets or sets x on the map, pixels.</summary>
    public int X { get; set; }

    /// <summary>Gets or sets y on the map, pixels.</summary>
    public int Y { get; set; }

    /// <summary>Gets or sets when it was dropped, Unix milliseconds.</summary>
    public long CreatedAtMs { get; set; }

    /// <summary>Gets or sets the account that caused the drop, or <see langword="null"/>.</summary>
    public Guid? CausedBy { get; set; }

    /// <summary>Gets or sets until when the cause has priority on a shared map, Unix milliseconds; zero when none.</summary>
    public long PriorityUntilMs { get; set; }

    /// <summary>Gets or sets when it vanishes, Unix milliseconds; zero when it never does.</summary>
    public long ExpiresAtMs { get; set; }
}
